def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = next(v for v in Counter(v for row in grid for v in row).most_common() if v[0] != bg)[0]
    h, w = len(grid), len(grid[0])
    # Bridge gaps between same-color markers along each row and column.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        if len(cols) >= 2:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

